(()=>{'use strict';const shared=document.body.classList.contains('shared-app');function names(t){return [...new Set((t.collaborators||[]).filter(id=>id!==(shared?t.owner_id:t.owner)))].map(id=>shared?person(id):people[id]).filter(Boolean)}function label(t){const n=names(t);if(!n.length)return null;const el=document.createElement('small');el.className='team-names-under-owner';el.textContent='همکاران: '+n.join('، ');return el}
function decorate(){document.querySelectorAll('.clarity-table tbody tr,.desk-task-card').forEach(row=>{if(row.dataset.peopleGrouped)return;const title=row.querySelector('[data-task],[data-shared-card]'),id=title?.dataset.task||title?.dataset.sharedCard,t=tasks.find(t=>t.id===id);if(!t)return;row.dataset.peopleGrouped='true';const extra=label(t);row.querySelectorAll('.task-collaborator-names,.task-collaborators').forEach(e=>e.remove());if(!extra)return;if(row.matches('tr')){row.children[1]?.append(extra)}else{const bottom=row.querySelector('.card-bottom');if(!bottom)return;const group=document.createElement('div');group.className='team-owner-group';const owner=bottom.firstElementChild;if(owner)group.append(owner);group.append(extra);bottom.prepend(group)}});const dialog=document.querySelector('dialog[open]');if(!dialog)return;const id=shared?selectedTask:typeof selectedRichTask!=='undefined'?selectedRichTask:null,t=tasks.find(t=>t.id===id);if(!t)return;const facts=dialog.querySelector('.shared-facts'),owner=facts&&[...facts.querySelectorAll('span')].find(e=>e.textContent.startsWith('مسئول:'));if(owner&&!owner.querySelector('.team-names-under-owner')){const extra=label(t);if(extra)owner.append(extra);dialog.querySelectorAll('p.shared-meta').forEach(p=>{if(p.textContent.startsWith('همکاران:'))p.remove()})}}
const oldRender=render;render=function(...a){const r=oldRender(...a);decorate();return r};const oldTasks=renderTasks;renderTasks=function(...a){const r=oldTasks(...a);decorate();return r};const oldDetail=detail;detail=async function(...a){const r=await oldDetail(...a);decorate();return r};decorate();})();
